insert into auth.permission(key,name_fa,category,description,is_sensitive) values('shop.view','دیدن فروشگاه','shop','کاتالوگ B2B',false),('shop.purchase','خرید کسب‌وکاری','shop','سبد و رزرو سفارش',true),('shop.manage','مدیریت فروشگاه','shop','محصول، موجودی و سفارش فروشنده',true) on conflict(key) do nothing;
insert into app.role_permission(role_id,permission_key) select r.id,p.key from app.role r cross join auth.permission p where r.business_id is null and r.key in('owner','admin') and p.key in('shop.view','shop.purchase','shop.manage') on conflict do nothing;
