('admin_shop','dashboard','داشبورد فروشگاه','/app','home','shop.manage','ready',10),('admin_shop','products','محصول‌ها','/app/products','box','shop.manage','ready',20),('admin_shop','stock','موجودی و رزرو','/app/stock','layers','shop.manage','ready',30),('admin_shop','orders','سفارش‌های ورودی','/app/orders','list','shop.manage','ready',40),('admin_shop','account','حساب و امنیت','/app/account','shield',null,'ready',50) on conflict(surface,key) do nothing;
insert into ops.page_budget(route_pattern,scope,name_fa,lcp_ms,inp_ms,cls,weight_kb,request_count,html_kb,css_kb,js_kb,font_kb) values('/products/:id','shop','صفحه محصول',2500,200,0.1,180,12,45,40,8,90),('/catalog','shop','کاتالوگ فروشگاه',2500,200,0.1,180,12,45,40,8,90) on conflict(scope,route_pattern) do nothing;
